package com.example.zavira_movil.detalleprogreso;

import android.graphics.Typeface;
import android.os.Bundle;
import android.view.*;
import android.widget.TextView;
import androidx.annotation.*;
import androidx.fragment.app.Fragment;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import com.example.zavira_movil.R;

public class FragmentDetalleResumen extends Fragment {
    private TextView tvMensaje, tvNivelActual, tvNivelActualValue;
    private android.view.View llNivelActual;
    private RecyclerView rvStats;
    private ProgresoDetalleResponse data;
    private String materia;

    public void setData(ProgresoDetalleResponse data) {
        this.data = data;
        if (getView() != null && isAdded()) bind();
    }

    public void setMateria(String materia) {
        this.materia = materia;
        if (getView() != null && isAdded()) bind();
    }

    @Nullable @Override
    public View onCreateView(@NonNull LayoutInflater inf, @Nullable ViewGroup c, @Nullable Bundle s) {
        View v = inf.inflate(R.layout.fragment_detalle_resumen, c, false);
        tvMensaje = v.findViewById(R.id.tvMensaje);
        tvNivelActual = v.findViewById(R.id.tvNivelActual);
        tvNivelActualValue = v.findViewById(R.id.tvNivelActualValue);
        llNivelActual = v.findViewById(R.id.llNivelActual);
        rvStats = v.findViewById(R.id.rvStats);
        if (getContext() != null) {
            rvStats.setLayoutManager(new LinearLayoutManager(getContext()));
        }
        if (data != null && isAdded()) bind();
        return v;
    }

    private void bind() {
        if (!isAdded() || getContext() == null) return;
        if (data == null || data.resumen == null || data.header == null) return;
        if (tvMensaje == null) return;

        // Mensaje centrado con signos de admiración y negrita
        String mensaje = data.resumen.mensaje != null ? data.resumen.mensaje.trim() : "";
        if (!mensaje.isEmpty()) {
            // Agregar signo de apertura si no existe
            if (!mensaje.startsWith("¡")) {
                mensaje = "¡" + mensaje;
            }
            // Agregar signo de cierre si no existe
            if (!mensaje.endsWith("!") && !mensaje.endsWith("¡")) {
                mensaje = mensaje + "!";
            }
        }
        tvMensaje.setText(mensaje);
        tvMensaje.setGravity(Gravity.CENTER);
        tvMensaje.setTypeface(null, Typeface.BOLD);

        // Nivel actual: negrita y alineado con estadísticas
        // Ocultar si es "Todas las áreas" o "Isla del Conocimiento"
        if (materia != null) {
            String m = materia.toLowerCase().trim();
            boolean esTodasLasAreas = m.contains("conocimiento") || m.contains("isla") || 
                (m.contains("todas") && (m.contains("area") || m.contains("área")));

            if (esTodasLasAreas) {
                if (llNivelActual != null) {
                    llNivelActual.setVisibility(View.GONE);
                }
            } else {
                if (llNivelActual != null) {
                    llNivelActual.setVisibility(View.VISIBLE);
                }
                if (tvNivelActual != null) {
                    tvNivelActual.setText("Nivel actual:");
                    tvNivelActual.setTypeface(null, Typeface.BOLD);
                }
                if (tvNivelActualValue != null) {
                    tvNivelActualValue.setText(String.valueOf(data.resumen.nivelActual));
                    tvNivelActualValue.setTypeface(null, Typeface.BOLD);
                }
            }
        } else {
            if (llNivelActual != null) {
                llNivelActual.setVisibility(View.VISIBLE);
            }
            if (tvNivelActual != null) {
                tvNivelActual.setText("Nivel actual:");
                tvNivelActual.setTypeface(null, Typeface.BOLD);
            }
            if (tvNivelActualValue != null) {
                tvNivelActualValue.setText(String.valueOf(data.resumen.nivelActual));
                tvNivelActualValue.setTypeface(null, Typeface.BOLD);
            }
        }

        if (rvStats != null) {
            rvStats.setAdapter(new ResumenAdapter(
                    data.header.total,
                    data.header.correctas,
                    data.header.incorrectas,
                    data.header.tiempo_total_seg
            ));
        }
    }
}

package com.example.zavira_movil.detalleprogreso;

import android.graphics.Typeface;
import android.os.Bundle;
import android.view.*;
import android.widget.TextView;
import androidx.annotation.*;
import androidx.fragment.app.Fragment;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import com.example.zavira_movil.R;
import com.google.android.material.progressindicator.CircularProgressIndicator;

import java.util.List;

public class FragmentDetalleResumen extends Fragment {
    private TextView tvMensaje, tvNivelActual, tvNivelActualValue;
    private android.view.View llNivelActual;
    private RecyclerView rvStats;
    private ProgresoDetalleResponse data;
    private String materia;

    // Nuevas vistas
    private CircularProgressIndicator progresoResumen;
    private TextView tvPctCenter, tvBadgeCorrectas, tvBadgeIncorrectas, tvBadgeTiempo;
    private android.view.View llRecomendaciones;
    private android.view.View containerRecomendaciones;

    public void setData(ProgresoDetalleResponse data) {
        this.data = data;
        if (getView() != null && isAdded()) bind();
    }
    
    public void setMateria(String materia) {
        this.materia = materia;
        if (getView() != null && isAdded()) bind();
    }

    @Nullable @Override
    public View onCreateView(@NonNull LayoutInflater inf, @Nullable ViewGroup c, @Nullable Bundle s) {
        View v = inf.inflate(R.layout.fragment_detalle_resumen, c, false);
        tvMensaje = v.findViewById(R.id.tvMensaje);
        tvNivelActual = v.findViewById(R.id.tvNivelActual);
        tvNivelActualValue = v.findViewById(R.id.tvNivelActualValue);
        llNivelActual = v.findViewById(R.id.llNivelActual);
        rvStats = v.findViewById(R.id.rvStats);

        // nuevas vistas
        progresoResumen = v.findViewById(R.id.progresoResumen);
        tvPctCenter = v.findViewById(R.id.tvPctCenter);
        tvBadgeCorrectas = v.findViewById(R.id.tvBadgeCorrectas);
        tvBadgeIncorrectas = v.findViewById(R.id.tvBadgeIncorrectas);
        tvBadgeTiempo = v.findViewById(R.id.tvBadgeTiempo);
        llRecomendaciones = v.findViewById(R.id.llRecomendaciones);
        containerRecomendaciones = v.findViewById(R.id.containerRecomendaciones);

        if (getContext() != null) {
            rvStats.setLayoutManager(new LinearLayoutManager(getContext()));
        }
        if (data != null && isAdded()) bind();
        return v;
    }

    private void bind() {
        if (!isAdded() || getContext() == null) return;
        if (data == null || data.resumen == null || data.header == null) return;
        if (tvMensaje == null) return;
        
        // Mensaje centrado con signos de admiración y negrita
        String mensaje = data.resumen.mensaje != null ? data.resumen.mensaje.trim() : "";
        if (!mensaje.isEmpty()) {
            // Agregar signo de apertura si no existe
            if (!mensaje.startsWith("¡")) {
                mensaje = "¡" + mensaje;
            }
            // Agregar signo de cierre si no existe
            if (!mensaje.endsWith("!") && !mensaje.endsWith("¡")) {
                mensaje = mensaje + "!";
            }
        }
        tvMensaje.setText(mensaje);
        tvMensaje.setGravity(Gravity.CENTER);
        tvMensaje.setTypeface(null, Typeface.BOLD);
        
        // Nivel actual: mostrar u ocultar
        if (materia != null) {
            String m = materia.toLowerCase().trim();
            boolean esTodasLasAreas = m.contains("conocimiento") || m.contains("isla") || 
                (m.contains("todas") && (m.contains("area") || m.contains("área")));
            if (esTodasLasAreas) {
                if (llNivelActual != null) llNivelActual.setVisibility(View.GONE);
            } else {
                if (llNivelActual != null) llNivelActual.setVisibility(View.VISIBLE);
                if (tvNivelActual != null) {
                    tvNivelActual.setText("Nivel actual:");
                    tvNivelActual.setTypeface(null, Typeface.BOLD);
                }
                if (tvNivelActualValue != null) {
                    tvNivelActualValue.setText(String.valueOf(data.resumen.nivelActual));
                    tvNivelActualValue.setTypeface(null, Typeface.BOLD);
                }
            }
        } else {
            if (llNivelActual != null) llNivelActual.setVisibility(View.VISIBLE);
            if (tvNivelActual != null) { tvNivelActual.setText("Nivel actual:"); tvNivelActual.setTypeface(null, Typeface.BOLD); }
            if (tvNivelActualValue != null) { tvNivelActualValue.setText(String.valueOf(data.resumen.nivelActual)); tvNivelActualValue.setTypeface(null, Typeface.BOLD); }
        }

        // Estadísticas: badges y progress
        int total = data.header.total;
        int correctas = data.header.correctas;
        int incorrectas = data.header.incorrectas;
        int tiempo = data.header.tiempo_total_seg;

        if (progresoResumen != null) {
            int pct = (data.header.escala != null && data.header.escala.equalsIgnoreCase("porcentaje")) ? data.header.puntaje
                    : (total > 0 ? Math.round(correctas * 100f / total) : 0);
            progresoResumen.setMax(100);
            progresoResumen.setProgress(pct);
            if (tvPctCenter != null) tvPctCenter.setText(String.format("%d%%", pct));
        }

        if (tvBadgeCorrectas != null) tvBadgeCorrectas.setText(String.format("%d\nCorrectas", correctas));
        if (tvBadgeIncorrectas != null) tvBadgeIncorrectas.setText(String.format("%d\nIncorrectas", incorrectas));
        if (tvBadgeTiempo != null) tvBadgeTiempo.setText(String.format("%ds\nTiempo", tiempo));

        // RecyclerView de estadísticas detalladas
        if (rvStats != null) {
            rvStats.setAdapter(new ResumenAdapter(total, correctas, incorrectas, tiempo));
        }

        // Recomendaciones: mostrar si hay datos en data.analisis.recomendaciones (si existe)
        if (llRecomendaciones != null && containerRecomendaciones != null) {
            containerRecomendaciones.setVisibility(View.GONE);
            if (data.analisis != null) {
                List<String> recs = null;
                try { recs = data.analisis.recomendaciones; } catch (Exception e) { recs = null; }
                if (recs != null && !recs.isEmpty()) {
                    containerRecomendaciones.setVisibility(View.VISIBLE);
                    containerRecomendaciones.setFocusable(false);
                    containerRecomendaciones.clearFocus();
                    containerRecomendaciones.setVisibility(View.VISIBLE);
                    containerRecomendaciones.setEnabled(true);
                    // limpiar
                    if (containerRecomendaciones instanceof android.view.ViewGroup) {
                        ((android.view.ViewGroup) containerRecomendaciones).removeAllViews();
                        for (String r : recs) {
                            TextView t = new TextView(getContext());
                            t.setText("• " + r);
                            t.setPadding(6,6,6,6);
                            ((android.view.ViewGroup) containerRecomendaciones).addView(t);
                        }
                        llRecomendaciones.setVisibility(View.VISIBLE);
                    }
                } else {
                    llRecomendaciones.setVisibility(View.GONE);
                }
            } else {
                llRecomendaciones.setVisibility(View.GONE);
            }
        }
    }
}

package com.example.zavira_movil.detalleprogreso;

import android.graphics.Color;
import android.os.Bundle;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.ProgressBar;
import android.widget.TextView;
import android.widget.Toast;
import android.util.Log;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.core.content.ContextCompat;
import androidx.fragment.app.Fragment;
import androidx.viewpager2.widget.ViewPager2;

import com.example.zavira_movil.R;
import com.example.zavira_movil.remote.RetrofitClient;
import com.google.android.material.tabs.TabLayout;
import com.google.android.material.tabs.TabLayoutMediator;

import retrofit2.Call;
import retrofit2.Callback;
import retrofit2.Response;
import retrofit2.http.GET;
import retrofit2.http.Path;

public class FragmentDetalleSimulacro extends Fragment {

    // ---- Vistas del header (usa tus IDs reales del layout) ----
    private TextView tvMateria, tvFecha, tvPuntaje, tvNivel, tvTiempo, tvCorr, tvInc;
    private ProgressBar progress;

    // ---- ViewPager + Adapter ----
    private DetalleSimuPagerAdapter pagerAdapter;

    // ---- Servicio local (no toca tu ApiService global) ----
    interface ProgresoService {
        @GET("movil/sesion/{id}/detalle")
        Call<ProgresoDetalleResponse> getDetalleSesion(@Path("id") int id);
    }

    @Nullable
    @Override
    public View onCreateView(@NonNull LayoutInflater inflater,
                             @Nullable ViewGroup container,
                             @Nullable Bundle savedInstanceState) {

        View v = inflater.inflate(R.layout.fragment_detalle_simulacro, container, false);

        // Header
        tvMateria = v.findViewById(R.id.tvMateria);
        tvFecha   = v.findViewById(R.id.tvFecha);
        tvPuntaje = v.findViewById(R.id.tvPuntaje);
        tvNivel   = v.findViewById(R.id.tvNivel);
        tvTiempo  = v.findViewById(R.id.tvTiempo);
        tvCorr    = v.findViewById(R.id.tvCorrectas);
        tvInc     = v.findViewById(R.id.tvIncorrectas);
        progress  = v.findViewById(R.id.progress);

        // Pager + Tabs
        ViewPager2 pager = v.findViewById(R.id.viewPager);
        pagerAdapter = new DetalleSimuPagerAdapter(requireActivity());
        pager.setAdapter(pagerAdapter);

        TabLayout tabs = v.findViewById(R.id.tabLayout);
        // El TabLayout ya está configurado en el XML con fondo azul oscuro y texto blanco
        new TabLayoutMediator(tabs, pager, (tab, position) -> {
            if (position == 0) tab.setText("Resumen");
            else if (position == 1) tab.setText("Preguntas");
            else tab.setText("Análisis");
        }).attach();

        // Tab inicial: lee "initial_tab" si te lo mandan (por defecto 0 = Resumen)
        int initialTab = getArguments() != null ? getArguments().getInt("initial_tab", 0) : 0;
        pager.setCurrentItem(Math.max(0, Math.min(2, initialTab)), false);

        // id de sesión (OBLIGATORIO)
        int idSesion = getArguments() != null ? getArguments().getInt("id_sesion", 0) : 0;
        cargarDatos(idSesion);

        return v;
    }

    @Override
    public void onViewCreated(@NonNull View view, @Nullable Bundle savedInstanceState) {
        super.onViewCreated(view, savedInstanceState);

        // Aplicar recarga por detalle ANTES de configurar padding
        // Esto asegura que la recarga se aplique cuando el usuario realmente ve el detalle
        aplicarRecargaPorDetalle();

        // Configurar padding del contenedor para bajar el contenido
        if (getActivity() != null) {
            android.widget.FrameLayout fragmentContainer = getActivity().findViewById(R.id.fragmentContainer);
            if (fragmentContainer != null) {
                // Usar post para asegurar que se aplique después de que la vista esté completamente montada
                fragmentContainer.post(() -> {
                    int paddingTop = (int) (40 * getResources().getDisplayMetrics().density); // 40dp
                    fragmentContainer.setPadding(0, paddingTop, 0, 0);
                });
                // También aplicar inmediatamente
                int paddingTop = (int) (40 * getResources().getDisplayMetrics().density); // 40dp
                fragmentContainer.setPadding(0, paddingTop, 0, 0);
            }
        }
    }

    /**
     * Aplica recarga de media vida por ver el detalle.
     * Solo funciona una vez por intento fallido.
     */
    private void aplicarRecargaPorDetalle() {
        try {
            // Obtener datos de los argumentos
            Bundle args = getArguments();
            if (args == null) {
                Log.w("FragmentDetalleSimulacro", "No se encontraron argumentos para aplicar recarga");
                return;
            }

            // Obtener materia y nivel
            String materia = args.getString("materia");
            int nivel = args.getInt("nivel", 0);

            if (materia == null || materia.isEmpty() || nivel <= 1) {
                Log.d("FragmentDetalleSimulacro", "No se aplica recarga: materia=" + materia + ", nivel=" + nivel);
                return;
            }

            // Obtener userId
            int userId = com.example.zavira_movil.local.TokenManager.getUserId(requireContext());
            if (userId <= 0) {
                Log.w("FragmentDetalleSimulacro", "No se pudo obtener userId");
                return;
            }

            // Aplicar recarga
            boolean recargado = com.example.zavira_movil.niveleshome.LivesManager.recargarPorDetalle(
                requireContext(),
                String.valueOf(userId),
                materia,
                nivel
            );

            if (recargado) {
                Log.d("FragmentDetalleSimulacro", "¡Media vida recargada al ver detalle!");
                Toast.makeText(requireContext(), "✨ ¡Media vida recargada!", Toast.LENGTH_SHORT).show();

                // Notificar a HomeActivity para actualizar UI de vidas
                if (getActivity() instanceof com.example.zavira_movil.Home.HomeActivity) {
                    // El HomeActivity debería tener un método para actualizar las vidas en el UI
                    // Por ahora, solo enviar un broadcast local
                    androidx.localbroadcastmanager.content.LocalBroadcastManager.getInstance(requireContext())
                        .sendBroadcast(new android.content.Intent("UPDATE_LIVES"));
                }
            } else {
                Log.d("FragmentDetalleSimulacro", "No se pudo aplicar recarga (ya usada o no disponible)");
            }
        } catch (Exception e) {
            Log.e("FragmentDetalleSimulacro", "Error al aplicar recarga por detalle", e);
        }
    }

    private void cargarDatos(int idSesion) {
        if (!isAdded() || getContext() == null) return;

        if (idSesion <= 0) {
            Toast.makeText(getContext(), "Falta id del intento", Toast.LENGTH_LONG).show();
            return;
        }

        if (progress != null) progress.setVisibility(View.VISIBLE);

        // Usa tu RetrofitClient ya configurado (token, baseUrl, etc.)
        ProgresoService api = RetrofitClient
                .getInstance()
                .create(ProgresoService.class);

        Log.d("DETALLE_SIMU", "GET /movil/sesion/" + idSesion + "/detalle");

        api.getDetalleSesion(idSesion).enqueue(new Callback<>() {
            @Override
            public void onResponse(@NonNull Call<ProgresoDetalleResponse> call, @NonNull Response<ProgresoDetalleResponse> resp) {
                if (!isAdded() || getContext() == null) return;
                if (progress != null) progress.setVisibility(View.GONE);

                Log.d("DETALLE_SIMU", "========================================");
                Log.d("DETALLE_SIMU", " RESPUESTA RECIBIDA DEL BACKEND");
                Log.d("DETALLE_SIMU", "========================================");
                Log.d("DETALLE_SIMU", "HTTP Status: " + resp.code());
                Log.d("DETALLE_SIMU", "Successful: " + resp.isSuccessful());

                if (!resp.isSuccessful() || resp.body() == null) {
                    Log.e("DETALLE_SIMU", "❌ ERROR: HTTP " + resp.code());
                    if (resp.body() == null) {
                        Log.e("DETALLE_SIMU", "❌ ERROR: Body es NULL");
                    }
                    if (getContext() != null) {
                        Toast.makeText(getContext(), "Error " + resp.code(), Toast.LENGTH_LONG).show();
                    }
                    return;
                }

                @NonNull ProgresoDetalleResponse d = resp.body();

                // Debugging detallado de la respuesta
                Log.d("DETALLE_SIMU", "========================================");
                Log.d("DETALLE_SIMU", " DATOS RECIBIDOS:");
                Log.d("DETALLE_SIMU", "========================================");

                if (d.header == null) {
                    Log.e("DETALLE_SIMU", "❌ ERROR: Header es NULL");
                    if (getContext() != null) {
                        Toast.makeText(getContext(), "Detalle sin header", Toast.LENGTH_SHORT).show();
                    }
                    return;
                }

                // Logging del header
                Log.d("DETALLE_SIMU", "✅ HEADER:");
                Log.d("DETALLE_SIMU", "  - Materia: " + d.header.materia);
                Log.d("DETALLE_SIMU", "  - Fecha: " + d.header.fecha);
                Log.d("DETALLE_SIMU", "  - Nivel: " + d.header.nivel);
                Log.d("DETALLE_SIMU", "  - Correctas: " + d.header.correctas);
                Log.d("DETALLE_SIMU", "  - Incorrectas: " + d.header.incorrectas);
                Log.d("DETALLE_SIMU", "  - Total: " + d.header.total);
                Log.d("DETALLE_SIMU", "  - Puntaje: " + d.header.puntaje);
                Log.d("DETALLE_SIMU", "  - Tiempo Total (seg): " + d.header.tiempo_total_seg);
                Log.d("DETALLE_SIMU", "  - Escala: " + d.header.escala);

                // Verificar si la sesión está vacía (usuario salió sin responder)
                if (d.header.total == 0 && (d.preguntas == null || d.preguntas.isEmpty())) {
                    Log.w("DETALLE_SIMU", "⚠️ SESIÓN VACÍA: El usuario salió sin responder ninguna pregunta");
                    Log.d("DETALLE_SIMU", "✅ PREGUNTAS: " + d.preguntas.size() + " preguntas");
                    for (int i = 0; i < Math.min(3, d.preguntas.size()); i++) {
                        Log.d("DETALLE_SIMU", "  - Pregunta " + (i+1) + ": " +
                            (d.preguntas.get(i).enunciado != null ?
                                d.preguntas.get(i).enunciado.substring(0, Math.min(50, d.preguntas.get(i).enunciado.length())) + "..." :
                                "sin enunciado"));
                    }
                } else {
                    Log.w("DETALLE_SIMU", "⚠️ PREGUNTAS es NULL");
                }

                // Logging de análisis
                if (d.analisis != null) {
                    Log.d("DETALLE_SIMU", "✅ ANÁLISIS: Datos disponibles");
                    // Nota: Los campos específicos dependen de la estructura de ProgresoDetalleResponse.Analisis
                } else {
                    Log.w("DETALLE_SIMU", "⚠️ ANÁLISIS es NULL");
                }

                Log.d("DETALLE_SIMU", "========================================");
                Log.d("DETALLE_SIMU", " BINDING DATOS A LA UI");
                Log.d("DETALLE_SIMU", "========================================");

                bindHeader(d);

                if (pagerAdapter != null) {
                    Log.d("DETALLE_SIMU", "✅ PagerAdapter existe, configurando datos...");
                    // Primero establecer la materia, luego los datos
                    pagerAdapter.setMateria(nullSafe(d.header.materia));
                    pagerAdapter.setData(d); // -> Resumen, Preguntas, Análisis
                    Log.d("DETALLE_SIMU", "✅ Datos configurados en PagerAdapter");
                } else {
                    Log.e("DETALLE_SIMU", "❌ ERROR: PagerAdapter es NULL");
                }

                Log.d("DETALLE_SIMU", "========================================");
            }

            @Override
            public void onFailure(@NonNull Call<ProgresoDetalleResponse> call, @NonNull Throwable t) {
                if (!isAdded() || getContext() == null) return;
                if (progress != null) progress.setVisibility(View.GONE);
                Log.e("DETALLE_SIMU", "onFailure", t);
                if (getContext() != null) {
                    Toast.makeText(getContext(), "Red: " + (t.getMessage() != null ? t.getMessage() : "Error desconocido"), Toast.LENGTH_LONG).show();
                }
            }
        });
    }

    private void bindHeader(ProgresoDetalleResponse d) {
        if (!isAdded() || getContext() == null) return;
        if (d == null || d.header == null) return;

        Log.d("DETALLE_SIMU", " BIND HEADER - Iniciando...");

        ProgresoDetalleResponse.Header h = d.header;
        android.content.Context ctx = getContext();

        // Texto principal
        if (tvMateria != null) {
            tvMateria.setText(nullSafe(h.materia));
            Log.d("DETALLE_SIMU", "✅ tvMateria actualizado: " + nullSafe(h.materia));
        } else {
            Log.e("DETALLE_SIMU", "❌ tvMateria es NULL");
        }

        if (tvFecha != null) {
            String fechaFormateada = formatFecha(h.fecha);
            tvFecha.setText(fechaFormateada);
            tvFecha.setTextColor(Color.BLACK);
            tvFecha.setTypeface(tvFecha.getTypeface(), android.graphics.Typeface.BOLD);
            Log.d("DETALLE_SIMU", "✅ tvFecha actualizado: " + fechaFormateada);
        } else {
            Log.e("DETALLE_SIMU", "❌ tvFecha es NULL");
        }

        if (tvNivel != null) {
            tvNivel.setText(nullSafe(h.nivel));
            Log.d("DETALLE_SIMU", "✅ tvNivel actualizado: " + nullSafe(h.nivel));
        } else {
            Log.e("DETALLE_SIMU", "❌ tvNivel es NULL");
        }

        if (tvTiempo != null) {
            String tiempoFormateado = toMin(h.tiempo_total_seg);
            tvTiempo.setText(tiempoFormateado);
            tvTiempo.setTextColor(ContextCompat.getColor(ctx, R.color.blue_time));
            Log.d("DETALLE_SIMU", "✅ tvTiempo actualizado: " + tiempoFormateado + " (seg: " + h.tiempo_total_seg + ")");
        } else {
            Log.e("DETALLE_SIMU", "❌ tvTiempo es NULL");
        }

        if (tvCorr != null) {
            tvCorr.setText(String.valueOf(h.correctas));
            tvCorr.setTextColor(ContextCompat.getColor(ctx, R.color.green_success));
            Log.d("DETALLE_SIMU", "✅ tvCorr (correctas) actualizado: " + h.correctas);
        } else {
            Log.e("DETALLE_SIMU", "❌ tvCorr es NULL");
        }

        if (tvInc != null) {
            tvInc.setText(String.valueOf(h.incorrectas));
            tvInc.setTextColor(ContextCompat.getColor(ctx, R.color.red_error));
            Log.d("DETALLE_SIMU", "✅ tvInc (incorrectas) actualizado: " + h.incorrectas);
        } else {
            Log.e("DETALLE_SIMU", "❌ tvInc es NULL");
        }

        // Porcentaje: si escala=porcentaje usa puntaje; si no, calcula según correctas/total
        int pct = (h.escala != null && h.escala.equalsIgnoreCase("porcentaje"))
                ? h.puntaje
                : (h.total > 0 ? Math.round(h.correctas * 100f / h.total) : 0);

        Log.d("DETALLE_SIMU", " Cálculo porcentaje:");
        Log.d("DETALLE_SIMU", "  - Escala: " + h.escala);
        Log.d("DETALLE_SIMU", "  - Puntaje: " + h.puntaje);
        Log.d("DETALLE_SIMU", "  - Correctas: " + h.correctas + " / Total: " + h.total);
        Log.d("DETALLE_SIMU", "  - Porcentaje calculado: " + pct + "%");

        if (tvPuntaje != null) {
            tvPuntaje.setText(String.format("%d%%", pct));
            // Obtener color del área para el porcentaje
            int areaColor = obtenerColorArea(nullSafe(h.materia), ctx);
            tvPuntaje.setTextColor(areaColor);
            Log.d("DETALLE_SIMU", "✅ tvPuntaje actualizado: " + pct + "%");
        } else {
            Log.e("DETALLE_SIMU", "❌ tvPuntaje es NULL");
        }

        if (progress != null) {
            progress.setMax(100);
            progress.setProgress(pct);
            Log.d("DETALLE_SIMU", "✅ ProgressBar actualizado: " + pct + "/100");
        } else {
            Log.e("DETALLE_SIMU", "❌ ProgressBar es NULL");
        }

        Log.d("DETALLE_SIMU", " BIND HEADER - Completado");
        // La materia ya se pasa al adapter en onResponse antes de setData
    }

    private int obtenerColorArea(String area, android.content.Context ctx) {
        if (area == null || ctx == null) return Color.parseColor("#B6B9C2");
        String a = area.toLowerCase().trim();

        try {
            // Isla del Conocimiento / Todas las áreas - Amarillo
            if (a.contains("conocimiento") || a.contains("isla") || 
                (a.contains("todas") && (a.contains("area") || a.contains("área")))) {
                return ContextCompat.getColor(ctx, R.color.area_conocimiento);
            }

            if (a.contains("matem")) return ContextCompat.getColor(ctx, R.color.area_matematicas);
            if (a.contains("lengua") || a.contains("lectura") || a.contains("espa") || a.contains("critica")) 
                return ContextCompat.getColor(ctx, R.color.area_lenguaje);
            if (a.contains("social") || a.contains("ciudad")) 
                return ContextCompat.getColor(ctx, R.color.area_sociales);
            if (a.contains("cien") || a.contains("biolo") || a.contains("fis") || a.contains("quim")) 
                return ContextCompat.getColor(ctx, R.color.area_ciencias);
            if (a.contains("ingl")) 
                return ContextCompat.getColor(ctx, R.color.area_ingles);
        } catch (Exception e) {
            return Color.parseColor("#B6B9C2");
        }

        return Color.parseColor("#B6B9C2");
    }

    // ---------- Helpers ----------
    private String toMin(int seg) {
        int m = seg / 60, s = seg % 60;
        return (m > 0) ? (m + " min" + (s > 0 ? " " + s + "s" : "")) : (s + "s");
    }

    private String formatFecha(String iso) {
        return (iso != null && iso.length() >= 10) ? iso.substring(0, 10) : "";
    }

    private String nullSafe(String s) { return s == null ? "" : s; }

    private int safeInt(Integer i) { return i == null ? 0 : i; }
}

package com.example.zavira_movil.detalleprogreso;

import android.graphics.Color;
import android.os.Bundle;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.ProgressBar;
import android.widget.TextView;
import android.widget.Toast;
import android.util.Log;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.core.content.ContextCompat;
import androidx.fragment.app.Fragment;
import androidx.viewpager2.widget.ViewPager2;

import com.example.zavira_movil.R;
import com.example.zavira_movil.remote.RetrofitClient;
import com.google.android.material.tabs.TabLayout;
import com.google.android.material.tabs.TabLayoutMediator;

import java.util.Locale;

import retrofit2.Call;
import retrofit2.Callback;
import retrofit2.Response;
import retrofit2.http.GET;
import retrofit2.http.Path;

public class FragmentDetalleSimulacro extends Fragment {

    // ---- Vistas del header (usa tus IDs reales del layout) ----
    private TextView tvMateria, tvFecha, tvPuntaje, tvNivel, tvTiempo, tvCorr, tvInc;
    private ProgressBar progress;

    // ---- ViewPager + Adapter ----
    private DetalleSimuPagerAdapter pagerAdapter;

    // ---- Servicio local (no toca tu ApiService global) ----
    interface ProgresoService {
        @GET("movil/sesion/{id}/detalle")
        Call<ProgresoDetalleResponse> getDetalleSesion(@Path("id") int id);
    }

    @Nullable
    @Override
    public View onCreateView(@NonNull LayoutInflater inflater,
                             @Nullable ViewGroup container,
                             @Nullable Bundle savedInstanceState) {

        View v = inflater.inflate(R.layout.fragment_detalle_simulacro, container, false);

        // Header
        tvMateria = v.findViewById(R.id.tvMateria);
        tvFecha   = v.findViewById(R.id.tvFecha);
        tvPuntaje = v.findViewById(R.id.tvPuntaje);
        tvNivel   = v.findViewById(R.id.tvNivel);
        tvTiempo  = v.findViewById(R.id.tvTiempo);
        tvCorr    = v.findViewById(R.id.tvCorrectas);
        tvInc     = v.findViewById(R.id.tvIncorrectas);
        progress  = v.findViewById(R.id.progress);

        // Pager + Tabs
        ViewPager2 pager = v.findViewById(R.id.viewPager);
        pagerAdapter = new DetalleSimuPagerAdapter(requireActivity());
        pager.setAdapter(pagerAdapter);

        TabLayout tabs = v.findViewById(R.id.tabLayout);
        // El TabLayout ya está configurado en el XML con fondo azul oscuro y texto blanco
        new TabLayoutMediator(tabs, pager, (tab, position) -> {
            if (position == 0) tab.setText("Resumen");
            else if (position == 1) tab.setText("Preguntas");
            else tab.setText("Análisis");
        }).attach();

        // Tab inicial: lee "initial_tab" si te lo mandan (por defecto 0 = Resumen)
        int initialTab = getArguments() != null ? getArguments().getInt("initial_tab", 0) : 0;
        pager.setCurrentItem(Math.max(0, Math.min(2, initialTab)), false);

        // id de sesión (OBLIGATORIO)
        int idSesion = getArguments() != null ? getArguments().getInt("id_sesion", 0) : 0;
        cargarDatos(idSesion);

        return v;
    }

    @Override
    public void onViewCreated(@NonNull View view, @Nullable Bundle savedInstanceState) {
        super.onViewCreated(view, savedInstanceState);

        // Aplicar recarga por detalle ANTES de configurar padding
        // Esto asegura que la recarga se aplique cuando el usuario realmente ve el detalle
        aplicarRecargaPorDetalle();

        // Configurar padding del contenedor para bajar el contenido
        if (getActivity() != null) {
            android.widget.FrameLayout fragmentContainer = getActivity().findViewById(R.id.fragmentContainer);
            if (fragmentContainer != null) {
                // Usar post para asegurar que se aplique después de que la vista esté completamente montada
                fragmentContainer.post(() -> {
                    int paddingTop = (int) (40 * getResources().getDisplayMetrics().density); // 40dp
                    fragmentContainer.setPadding(0, paddingTop, 0, 0);
                });
                // También aplicar inmediatamente
                int paddingTop = (int) (40 * getResources().getDisplayMetrics().density); // 40dp
                fragmentContainer.setPadding(0, paddingTop, 0, 0);
            }
        }
    }

    /**
     * Aplica recarga de media vida por ver el detalle.
     * Solo funciona una vez por intento fallido.
     */
    private void aplicarRecargaPorDetalle() {
        try {
            // Obtener datos de los argumentos
            Bundle args = getArguments();
            if (args == null) {
                Log.w("FragmentDetalleSimulacro", "No se encontraron argumentos para aplicar recarga");
                return;
            }

            // Obtener materia y nivel
            String materia = args.getString("materia");
            int nivel = args.getInt("nivel", 0);

            if (materia == null || materia.isEmpty() || nivel <= 1) {
                Log.d("FragmentDetalleSimulacro", "No se aplica recarga: materia=" + materia + ", nivel=" + nivel);
                return;
            }

            // Obtener userId
            int userId = com.example.zavira_movil.local.TokenManager.getUserId(requireContext());
            if (userId <= 0) {
                Log.w("FragmentDetalleSimulacro", "No se pudo obtener userId");
                return;
            }

            // Aplicar recarga
            boolean recargado = com.example.zavira_movil.niveleshome.LivesManager.recargarPorDetalle(
                requireContext(),
                String.valueOf(userId),
                materia,
                nivel
            );

            if (recargado) {
                Log.d("FragmentDetalleSimulacro", "¡Media vida recargada al ver detalle!");
                Toast.makeText(requireContext(), "✨ ¡Media vida recargada!", Toast.LENGTH_SHORT).show();

                // Notificar a HomeActivity para actualizar UI de vidas
                if (getActivity() instanceof com.example.zavira_movil.Home.HomeActivity) {
                    // El HomeActivity debería tener un método para actualizar las vidas en el UI
                    // Por ahora, solo enviar un broadcast local
                    androidx.localbroadcastmanager.content.LocalBroadcastManager.getInstance(requireContext())
                        .sendBroadcast(new android.content.Intent("UPDATE_LIVES"));
                }
            } else {
                Log.d("FragmentDetalleSimulacro", "No se pudo aplicar recarga (ya usada o no disponible)");
            }
        } catch (Exception e) {
            Log.e("FragmentDetalleSimulacro", "Error al aplicar recarga por detalle", e);
        }
    }

    private void cargarDatos(int idSesion) {
        if (!isAdded() || getContext() == null) return;

        if (idSesion <= 0) {
            Toast.makeText(getContext(), "Falta id del intento", Toast.LENGTH_LONG).show();
            return;
        }

        if (progress != null) progress.setVisibility(View.VISIBLE);

        // Usa tu RetrofitClient ya configurado (token, baseUrl, etc.)
        ProgresoService api = RetrofitClient
                .getInstance()
                .create(ProgresoService.class);

        Log.d("DETALLE_SIMU", "GET /movil/sesion/" + idSesion + "/detalle");

        api.getDetalleSesion(idSesion).enqueue(new Callback<>() {
            @Override
            public void onResponse(@NonNull Call<ProgresoDetalleResponse> call, @NonNull Response<ProgresoDetalleResponse> resp) {
                if (!isAdded() || getContext() == null) return;
                if (progress != null) progress.setVisibility(View.GONE);

                Log.d("DETALLE_SIMU", "========================================");
                Log.d("DETALLE_SIMU", " RESPUESTA RECIBIDA DEL BACKEND");
                Log.d("DETALLE_SIMU", "========================================");
                Log.d("DETALLE_SIMU", "HTTP Status: " + resp.code());
                Log.d("DETALLE_SIMU", "Successful: " + resp.isSuccessful());

                if (!resp.isSuccessful() || resp.body() == null) {
                    Log.e("DETALLE_SIMU", "❌ ERROR: HTTP " + resp.code());
                    if (resp.body() == null) {
                        Log.e("DETALLE_SIMU", "❌ ERROR: Body es NULL");
                    }
                    if (getContext() != null) {
                        Toast.makeText(getContext(), "Error " + resp.code(), Toast.LENGTH_LONG).show();
                    }
                    return;
                }

                @NonNull ProgresoDetalleResponse d = resp.body();

                // Debugging detallado de la respuesta
                Log.d("DETALLE_SIMU", "========================================");
                Log.d("DETALLE_SIMU", " DATOS RECIBIDOS:");
                Log.d("DETALLE_SIMU", "========================================");

                if (d.header == null) {
                    Log.e("DETALLE_SIMU", "❌ ERROR: Header es NULL");
                    if (getContext() != null) {
                        Toast.makeText(getContext(), "Detalle sin header", Toast.LENGTH_SHORT).show();
                    }
                    return;
                }

                // Logging del header
                Log.d("DETALLE_SIMU", "✅ HEADER:");
                Log.d("DETALLE_SIMU", "  - Materia: " + d.header.materia);
                Log.d("DETALLE_SIMU", "  - Fecha: " + d.header.fecha);
                Log.d("DETALLE_SIMU", "  - Nivel: " + d.header.nivel);
                Log.d("DETALLE_SIMU", "  - Correctas: " + d.header.correctas);
                Log.d("DETALLE_SIMU", "  - Incorrectas: " + d.header.incorrectas);
                Log.d("DETALLE_SIMU", "  - Total: " + d.header.total);
                Log.d("DETALLE_SIMU", "  - Puntaje: " + d.header.puntaje);
                Log.d("DETALLE_SIMU", "  - Tiempo Total (seg): " + d.header.tiempo_total_seg);
                Log.d("DETALLE_SIMU", "  - Escala: " + d.header.escala);

                // Verificar preguntas
                if (d.preguntas != null && !d.preguntas.isEmpty()) {
                    Log.d("DETALLE_SIMU", "✅ PREGUNTAS: " + d.preguntas.size() + " preguntas");
                    for (int i = 0; i < Math.min(3, d.preguntas.size()); i++) {
                        Log.d("DETALLE_SIMU", "  - Pregunta " + (i+1) + ": " +
                            (d.preguntas.get(i).enunciado != null ?
                                d.preguntas.get(i).enunciado.substring(0, Math.min(50, d.preguntas.get(i).enunciado.length())) + "..." :
                                "sin enunciado"));
                    }
                } else {
                    Log.w("DETALLE_SIMU", "⚠️ PREGUNTAS es NULL o vacío");
                    // Verificar si la sesión está vacía (usuario salió sin responder)
                    if (d.header.total == 0) {
                        Log.w("DETALLE_SIMU", "⚠️ SESIÓN VACÍA: El usuario salió sin responder ninguna pregunta");
                    }
                }

                // Logging de análisis
                if (d.analisis != null) {
                    Log.d("DETALLE_SIMU", "✅ ANÁLISIS: Datos disponibles");
                    // Nota: Los campos específicos dependen de la estructura de ProgresoDetalleResponse.Analisis
                } else {
                    Log.w("DETALLE_SIMU", "⚠️ ANÁLISIS es NULL");
                }

                Log.d("DETALLE_SIMU", "========================================");
                Log.d("DETALLE_SIMU", " BINDING DATOS A LA UI");
                Log.d("DETALLE_SIMU", "========================================");

                bindHeader(d);

                // Forzar color blanco en chips tras bind (defensa contra overrides posteriores)
                forceChipTextWhite();

                if (pagerAdapter != null) {
                    Log.d("DETALLE_SIMU", "✅ PagerAdapter existe, configurando datos...");
                    // Primero establecer la materia, luego los datos
                    pagerAdapter.setMateria(nullSafe(d.header.materia));
                    pagerAdapter.setData(d); // -> Resumen, Preguntas, Análisis
                    // Reforzar color blanco en chips en caso de que setData provoque algún cambio visual
                    forceChipTextWhite();
                    Log.d("DETALLE_SIMU", "✅ Datos configurados en PagerAdapter");
                } else {
                    Log.e("DETALLE_SIMU", "❌ ERROR: PagerAdapter es NULL");
                }

                Log.d("DETALLE_SIMU", "========================================");
            }

            @Override
            public void onFailure(@NonNull Call<ProgresoDetalleResponse> call, @NonNull Throwable t) {
                if (!isAdded() || getContext() == null) return;
                if (progress != null) progress.setVisibility(View.GONE);
                Log.e("DETALLE_SIMU", "onFailure", t);
                if (getContext() != null) {
                    Toast.makeText(getContext(), "Red: " + (t.getMessage() != null ? t.getMessage() : "Error desconocido"), Toast.LENGTH_LONG).show();
                }
            }
        });
    }

    private void bindHeader(ProgresoDetalleResponse d) {
        if (!isAdded() || getContext() == null) return;
        if (d == null || d.header == null) return;

        Log.d("DETALLE_SIMU", " BIND HEADER - Iniciando...");

        ProgresoDetalleResponse.Header h = d.header;
        android.content.Context ctx = getContext();

        // Texto principal
        if (tvMateria != null) {
            tvMateria.setText(nullSafe(h.materia));
            Log.d("DETALLE_SIMU", "✅ tvMateria actualizado: " + nullSafe(h.materia));
        } else {
            Log.e("DETALLE_SIMU", "❌ tvMateria es NULL");
        }

        if (tvFecha != null) {
            String fechaFormateada = formatFecha(h.fecha);
            tvFecha.setText(fechaFormateada);
            tvFecha.setTextColor(Color.BLACK);
            tvFecha.setTypeface(tvFecha.getTypeface(), android.graphics.Typeface.BOLD);
            Log.d("DETALLE_SIMU", "✅ tvFecha actualizado: " + fechaFormateada);
        } else {
            Log.e("DETALLE_SIMU", "❌ tvFecha es NULL");
        }

        if (tvNivel != null) {
            tvNivel.setText(nullSafe(h.nivel));
            Log.d("DETALLE_SIMU", "✅ tvNivel actualizado: " + nullSafe(h.nivel));
        } else {
            Log.e("DETALLE_SIMU", "❌ tvNivel es NULL");
        }

        if (tvTiempo != null) {
            String tiempoFormateado = toMin(h.tiempo_total_seg);
            tvTiempo.setText(tiempoFormateado);
            // Mostrar texto blanco para contraste sobre el chip azul
            tvTiempo.setTextColor(ContextCompat.getColor(ctx, R.color.white));
            Log.d("DETALLE_SIMU", "✅ tvTiempo actualizado: " + tiempoFormateado + " (seg: " + h.tiempo_total_seg + ")");
        } else {
            Log.e("DETALLE_SIMU", "❌ tvTiempo es NULL");
        }

        if (tvCorr != null) {
            tvCorr.setText(String.valueOf(h.correctas));
            // Mostrar texto blanco para contraste sobre el chip verde
            tvCorr.setTextColor(ContextCompat.getColor(ctx, R.color.white));
            Log.d("DETALLE_SIMU", "✅ tvCorr (correctas) actualizado: " + h.correctas);
        } else {
            Log.e("DETALLE_SIMU", "❌ tvCorr es NULL");
        }

        if (tvInc != null) {
            tvInc.setText(String.valueOf(h.incorrectas));
            // Mostrar texto blanco para contraste sobre el chip rojo
            tvInc.setTextColor(ContextCompat.getColor(ctx, R.color.white));
            Log.d("DETALLE_SIMU", "✅ tvInc (incorrectas) actualizado: " + h.incorrectas);
        } else {
            Log.e("DETALLE_SIMU", "❌ tvInc es NULL");
        }

        // Porcentaje: si escala=porcentaje usa puntaje; si no, calcula según correctas/total
        int pct = (h.escala != null && h.escala.equalsIgnoreCase("porcentaje"))
                ? h.puntaje
                : (h.total > 0 ? Math.round(h.correctas * 100f / h.total) : 0);

        Log.d("DETALLE_SIMU", " Cálculo porcentaje:");
        Log.d("DETALLE_SIMU", "  - Escala: " + h.escala);
        Log.d("DETALLE_SIMU", "  - Puntaje: " + h.puntaje);
        Log.d("DETALLE_SIMU", "  - Correctas: " + h.correctas + " / Total: " + h.total);
        Log.d("DETALLE_SIMU", "  - Porcentaje calculado: " + pct + "%");

        if (tvPuntaje != null) {
            tvPuntaje.setText(String.format(Locale.getDefault(), "%d%%", pct));
            // Obtener color del área para el porcentaje
            int areaColor = obtenerColorArea(nullSafe(h.materia), ctx);
            tvPuntaje.setTextColor(areaColor);
            Log.d("DETALLE_SIMU", "✅ tvPuntaje actualizado: " + pct + "%");
        } else {
            Log.e("DETALLE_SIMU", "❌ tvPuntaje es NULL");
        }

        if (progress != null) {
            progress.setMax(100);
            progress.setProgress(pct);
            Log.d("DETALLE_SIMU", "✅ ProgressBar actualizado: " + pct + "/100");
        } else {
            Log.e("DETALLE_SIMU", "❌ ProgressBar es NULL");
        }

        Log.d("DETALLE_SIMU", " BIND HEADER - Completado");
        // La materia ya se pasa al adapter en onResponse antes de setData
    }

    private int obtenerColorArea(String area, android.content.Context ctx) {
        if (area == null || ctx == null) return Color.parseColor("#B6B9C2");
        String a = area.toLowerCase().trim();

        try {
            // Isla del Conocimiento / Todas las áreas - Amarillo
            if (a.contains("conocimiento") || a.contains("isla") || 
                (a.contains("todas") && (a.contains("area") || a.contains("área")))) {
                return ContextCompat.getColor(ctx, R.color.area_conocimiento);
            }

            if (a.contains("matem")) return ContextCompat.getColor(ctx, R.color.area_matematicas);
            if (a.contains("lengua") || a.contains("lectura") || a.contains("espa") || a.contains("critica")) 
                return ContextCompat.getColor(ctx, R.color.area_lenguaje);
            if (a.contains("social") || a.contains("ciudad")) 
                return ContextCompat.getColor(ctx, R.color.area_sociales);
            if (a.contains("cien") || a.contains("biolo") || a.contains("fis") || a.contains("quim")) 
                return ContextCompat.getColor(ctx, R.color.area_ciencias);
            if (a.contains("ingl")) 
                return ContextCompat.getColor(ctx, R.color.area_ingles);
        } catch (Exception e) {
            return Color.parseColor("#B6B9C2");
        }

        return Color.parseColor("#B6B9C2");
    }

    // ---------- Helpers ----------
    private String toMin(int seg) {
        int m = seg / 60, s = seg % 60;
        return (m > 0) ? (m + " min" + (s > 0 ? " " + s + "s" : "")) : (s + "s");
    }

    private String formatFecha(String iso) {
        return (iso != null && iso.length() >= 10) ? iso.substring(0, 10) : "";
    }

    private String nullSafe(String s) { return s == null ? "" : s; }

    /**
     * Fuerza el color de texto blanco en los chips de Correctas/Incorrectas/Tiempo.
     * Método defensivo: llamado tras bindHeader y tras setData.
     */
    private void forceChipTextWhite() {
        if (!isAdded() || getContext() == null) return;
        android.content.Context ctx = getContext();
        try {
            if (tvCorr != null) tvCorr.setTextColor(ContextCompat.getColor(ctx, R.color.white));
            if (tvInc != null) tvInc.setTextColor(ContextCompat.getColor(ctx, R.color.white));
            if (tvTiempo != null) tvTiempo.setTextColor(ContextCompat.getColor(ctx, R.color.white));
        } catch (Exception e) {
            Log.w("DETALLE_SIMU", "forceChipTextWhite error", e);
        }
    }
}

package com.example.zavira_movil.detalleprogreso;

import java.util.List;

public class ProgresoDetalleResponse {
    public Header header;
    public Resumen resumen;
    public List<Pregunta> preguntas;
    public Analisis analisis;

    public static class Header {
        public String materia;
        public String fecha;
        public String nivel;
        public int nivelOrden;
        public int puntaje;
        public String escala;
        public int tiempo_total_seg;
        public int correctas;
        public int incorrectas;
        public int total;
    }

    public static class Resumen {
        public String cambio;
        public String mensaje;
        public int nivelActual;
    }

    public static class Pregunta {
        public int orden;
        public int id_pregunta;
        public String area;
        public String subtema;
        public String enunciado;
        public String correcta;          // "A"|"B"|"C"|"D"
        public String marcada;           // "A"|"B"|"C"|"D"
        public boolean es_correcta;
        public String explicacion;
        public Integer tiempo_empleado_seg; // puede venir null
    }

    public static class Analisis {
        public List<String> fortalezas;
        public List<String> mejoras;
        public List<String> recomendaciones;
    }
}

package com.example.zavira_movil.detalleprogreso;

import com.google.gson.annotations.SerializedName;
import java.util.List;

public class ProgresoDetalleResponse {
    public Header header;
    public Resumen resumen;
    public List<Pregunta> preguntas;
    public Analisis analisis;

    public static class Header {
        public String materia;
        public String fecha;
        public String nivel;
        @SerializedName("nivelOrden")
        public Integer nivelOrden;  // Nullable para compatibilidad
        public int puntaje;
        public String escala;       // "porcentaje" o "ICFES"
        public int tiempo_total_seg;
        public int correctas;
        public int incorrectas;
        public int total;
    }

    public static class Resumen {
        public String cambio;
        public String mensaje;
        @SerializedName("nivelActual")
        public Integer nivelActual;  // Nullable para compatibilidad
    }

    public static class Pregunta {
        public int orden;
        @SerializedName("id_pregunta")
        public Integer id_pregunta;  // Nullable - puede ser null para preguntas de IA
        public String area;
        public String subtema;
        public String enunciado;
        public String correcta;          // "A"|"B"|"C"|"D"
        public String marcada;           // "A"|"B"|"C"|"D"
        public boolean es_correcta;
        public String explicacion;
        @SerializedName("tiempo_empleado_seg")
        public Integer tiempo_empleado_seg; // puede venir null
    }

    public static class Analisis {
        public List<String> fortalezas;
        @SerializedName("subtemas_a_mejorar")
        public List<String> subtemas_a_mejorar;  // Nuevo campo del backend
        public List<String> mejoras;
        public List<String> recomendaciones;
    }
}

package com.example.zavira_movil.detalleprogreso;

import android.graphics.Color;
import android.view.*;
import android.widget.TextView;
import androidx.annotation.NonNull;
import androidx.core.content.ContextCompat;
import androidx.recyclerview.widget.RecyclerView;

import com.example.zavira_movil.R;

public class ResumenAdapter extends RecyclerView.Adapter<ResumenAdapter.VH> {

    private final int total, correctas, incorrectas, tiempoSeg;

    public ResumenAdapter(int total, int correctas, int incorrectas, int tiempoSeg) {
        this.total = total; this.correctas = correctas; this.incorrectas = incorrectas; this.tiempoSeg = tiempoSeg;
    }

    @NonNull @Override public VH onCreateViewHolder(@NonNull ViewGroup p, int vt) {
        View v = LayoutInflater.from(p.getContext()).inflate(R.layout.item_resumen_estad, p, false);
        return new VH(v);
    }

    @Override public void onBindViewHolder(@NonNull VH h, int pos) {
        if (pos == 0) { 
            h.title.setText("Preguntas respondidas"); 
            h.value.setText(String.valueOf(total));
            h.value.setTextColor(Color.BLACK);
        }
        else if (pos == 1) { 
            h.title.setText("Respuestas correctas"); 
            h.value.setText(String.valueOf(correctas));
            h.value.setTextColor(ContextCompat.getColor(h.itemView.getContext(), R.color.green_success));
        }
        else if (pos == 2) { 
            h.title.setText("Respuestas incorrectas"); 
            h.value.setText(String.valueOf(incorrectas));
            h.value.setTextColor(ContextCompat.getColor(h.itemView.getContext(), R.color.red_error));
        }
        else { 
            h.title.setText("Tiempo empleado"); 
            h.value.setText(toMin(tiempoSeg));
            h.value.setTextColor(ContextCompat.getColor(h.itemView.getContext(), R.color.blue_time));
        }
    }

    @Override public int getItemCount() { return 4; }

    static class VH extends RecyclerView.ViewHolder {
        TextView title, value;
        VH(View v){ super(v); title=v.findViewById(R.id.tvTitle); value=v.findViewById(R.id.tvValue); }
    }

    private String toMin(int seg){ int m=seg/60, s=seg%60; return m>0? (m+" min"+(s>0?" "+s+"s":"")): s+"s"; }
}

package com.example.zavira_movil.detalleprogreso;

import android.content.res.ColorStateList;
import android.graphics.Color;
import android.view.*;
import android.widget.TextView;
import androidx.annotation.NonNull;
import androidx.core.content.ContextCompat;
import androidx.recyclerview.widget.RecyclerView;

import com.example.zavira_movil.R;

public class ResumenAdapter extends RecyclerView.Adapter<ResumenAdapter.VH> {

    private final int total, correctas, incorrectas, tiempoSeg;

    public ResumenAdapter(int total, int correctas, int incorrectas, int tiempoSeg) {
        this.total = total; this.correctas = correctas; this.incorrectas = incorrectas; this.tiempoSeg = tiempoSeg;
    }

    @NonNull @Override public VH onCreateViewHolder(@NonNull ViewGroup p, int vt) {
        View v = LayoutInflater.from(p.getContext()).inflate(R.layout.item_resumen_estad, p, false);
        return new VH(v);
    }

    @Override public void onBindViewHolder(@NonNull VH h, int pos) {
        if (pos == 0) {
            h.title.setText("Preguntas respondidas");
            h.value.setText(String.valueOf(total));
            h.value.setTextColor(Color.BLACK);
            h.icon.setText("Q");
            h.subtitle.setVisibility(View.GONE);
            h.icon.setBackgroundTintList(ColorStateList.valueOf(ContextCompat.getColor(h.itemView.getContext(), R.color.gray_200)));
        }
        else if (pos == 1) {
            h.title.setText("Respuestas correctas");
            h.value.setText(String.valueOf(correctas));
            h.value.setTextColor(ContextCompat.getColor(h.itemView.getContext(), R.color.green_success));
            int pct = total > 0 ? Math.round((correctas * 100f) / total) : 0;
            h.icon.setText("✓");
            h.subtitle.setText(pct + "% de aciertos");
            h.subtitle.setVisibility(View.VISIBLE);
            h.icon.setBackgroundTintList(ColorStateList.valueOf(ContextCompat.getColor(h.itemView.getContext(), R.color.area_matematicas)));
        }
        else if (pos == 2) {
            h.title.setText("Respuestas incorrectas");
            h.value.setText(String.valueOf(incorrectas));
            h.value.setTextColor(ContextCompat.getColor(h.itemView.getContext(), R.color.red_error));
            int pct = total > 0 ? Math.round((incorrectas * 100f) / total) : 0;
            h.icon.setText("✗");
            h.subtitle.setText(pct + "% incorrectas");
            h.subtitle.setVisibility(View.VISIBLE);
            h.icon.setBackgroundTintList(ColorStateList.valueOf(ContextCompat.getColor(h.itemView.getContext(), R.color.area_sociales)));
        }
        else {
            h.title.setText("Tiempo empleado");
            h.value.setText(toMin(tiempoSeg));
            h.value.setTextColor(ContextCompat.getColor(h.itemView.getContext(), R.color.blue_time));
            h.icon.setText("⏱");
            h.subtitle.setText("Duración total");
            h.subtitle.setVisibility(View.VISIBLE);
            h.icon.setBackgroundTintList(ColorStateList.valueOf(ContextCompat.getColor(h.itemView.getContext(), R.color.blue_time)));
        }
    }

    @Override public int getItemCount() { return 4; }

    static class VH extends RecyclerView.ViewHolder {
        TextView title, value, icon, subtitle;
        VH(View v){ super(v); title=v.findViewById(R.id.tvTitle); value=v.findViewById(R.id.tvValue); icon=v.findViewById(R.id.tvIcon); subtitle=v.findViewById(R.id.tvSubtitle); }
    }

    private String toMin(int seg){ int m=seg/60, s=seg%60; return m>0? (m+" min"+(s>0?" "+s+"s":"")): s+"s"; }
}

package com.example.zavira_movil.progreso;

import android.graphics.drawable.GradientDrawable;
import android.util.TypedValue;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.ImageView;
import android.widget.TextView;

import androidx.annotation.NonNull;
import androidx.core.content.ContextCompat;
import androidx.recyclerview.widget.RecyclerView;

import com.example.zavira_movil.R;

import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Date;
import java.util.List;
import java.util.Locale;
import java.util.TimeZone;

public class HistorialAdapter extends RecyclerView.Adapter<HistorialAdapter.VH> {
    // callback para abrir detalle SOLO con la flecha
    public interface OnItemClick { void onClick(HistorialItem item); }
    private OnItemClick onItemClick;
    public void setOnItemClick(OnItemClick l) { this.onItemClick = l; }

    private final List<HistorialItem> data = new ArrayList<>();

    public void setData(List<HistorialItem> nuevos) {
        data.clear();
        if (nuevos != null) data.addAll(nuevos);
        notifyDataSetChanged();
    }

    @NonNull @Override
    public VH onCreateViewHolder(@NonNull ViewGroup parent, int viewType) {
        View v = LayoutInflater.from(parent.getContext())
                .inflate(R.layout.item_historial, parent, false);
        return new VH(v);
    }

    @Override
    public void onBindViewHolder(@NonNull VH h, int pos) {
        HistorialItem it = data.get(pos);

        // Texto base
        h.tvMateria.setText(it.getMateria());
        h.tvNivel.setText(it.getNivel());
        h.tvFecha.setText(formatFecha(it.getFecha()));

        // Mostrar correctas, incorrectas y total
        if (h.tvCorrectas != null) {
            h.tvCorrectas.setText(String.valueOf(it.getCorrectas()));
        }
        if (h.tvIncorrectas != null) {
            h.tvIncorrectas.setText(String.valueOf(it.getIncorrectas()));
        }
        if (h.tvTotal != null) {
            h.tvTotal.setText(String.valueOf(it.getTotal()));
        }

        // Puntico por materia (a la izquierda del nombre)
        int subjectColor = colorForSubject(h.itemView.getContext(), it.getMateria());
        GradientDrawable dot = new GradientDrawable();
        dot.setShape(GradientDrawable.OVAL);
        dot.setColor(subjectColor);
        int dotSize = dp(h.itemView, 10);
        dot.setSize(dotSize, dotSize);
        dot.setBounds(0, 0, dotSize, dotSize);
        h.tvMateria.setCompoundDrawablesRelative(dot, null, null, null);
        h.tvMateria.setCompoundDrawablePadding(dp(h.itemView, 8));

        // SOLO la FLECHA navega
        if (h.ivFlecha != null) {
            h.ivFlecha.setOnClickListener(v -> {
                int p = h.getBindingAdapterPosition();
                if (p != RecyclerView.NO_POSITION && onItemClick != null) {
                    onItemClick.onClick(data.get(p));
                }
            });
        }

        //  Sin acciones en el resto de la celda
        h.itemView.setOnClickListener(null);
        h.tvMateria.setOnClickListener(null);
        h.tvNivel.setOnClickListener(null);
        h.tvFecha.setOnClickListener(null);
        h.itemView.setClickable(false);
        h.tvMateria.setClickable(false);
        h.tvNivel.setClickable(false);
        h.tvFecha.setClickable(false);
    }

    @Override public int getItemCount() { return data.size(); }

    static class VH extends RecyclerView.ViewHolder {
        TextView tvMateria, tvNivel, tvFecha, tvCorrectas, tvIncorrectas, tvTotal;
        ImageView ivFlecha;

        VH(@NonNull View v) {
            super(v);
            tvMateria = v.findViewById(R.id.tvMateria);
            tvNivel   = v.findViewById(R.id.tvNivel);
            tvFecha   = v.findViewById(R.id.tvFecha);
            tvCorrectas = v.findViewById(R.id.tvCorrectas);
            tvIncorrectas = v.findViewById(R.id.tvIncorrectas);
            tvTotal = v.findViewById(R.id.tvTotal);
            ivFlecha  = v.findViewById(R.id.ivFlecha);
        }
    }

    // ---------- Helpers ----------
    private int colorForSubject(android.content.Context ctx, String materiaRaw) {
        if (materiaRaw == null) return ContextCompat.getColor(ctx, R.color.subject_default);
        String n = materiaRaw.trim().toLowerCase(Locale.getDefault());
        if (n.contains("mate"))   return ContextCompat.getColor(ctx, R.color.area_matematicas);
        if (n.contains("leng") || n.contains("lect") || n.contains("comuni"))
            return ContextCompat.getColor(ctx, R.color.area_lenguaje);
        if (n.contains("cien") || n.contains("biol") || n.contains("fis") || n.contains("quím") || n.contains("quim"))
            return ContextCompat.getColor(ctx, R.color.area_ciencias);
        if (n.contains("socia") || n.contains("hist") || n.contains("filo") || n.contains("ciudad"))
            return ContextCompat.getColor(ctx, R.color.area_sociales);
        if (n.contains("ingl") || n.contains("english"))
            return ContextCompat.getColor(ctx, R.color.area_ingles);
        return ContextCompat.getColor(ctx, R.color.subject_default);
    }

    private int dp(View view, int dp) {
        return Math.round(TypedValue.applyDimension(
                TypedValue.COMPLEX_UNIT_DIP, dp, view.getResources().getDisplayMetrics()));
    }

    private String formatFecha(String raw) {
        if (raw == null) return "";
        String s = raw.trim();
        if (s.isEmpty()) return "";
        try {
            if (s.matches("^\\d{10,}$")) {
                long epoch = Long.parseLong(s);
                Date d = new Date(s.length() == 10 ? epoch * 1000L : epoch);
                return outFmt().format(d);
            }
        } catch (Exception ignored) {}
        String[] patterns = new String[] {
                "yyyy-MM-dd'T'HH:mm:ss.SSSX",
                "yyyy-MM-dd'T'HH:mm:ssX",
                "yyyy-MM-dd HH:mm:ss",
                "yyyy-MM-dd"
        };
        for (String p : patterns) {
            try {
                SimpleDateFormat in = new SimpleDateFormat(p, Locale.getDefault());
                if (p.contains("X")) in.setTimeZone(TimeZone.getTimeZone("UTC"));
                Date d = in.parse(s);
                if (d != null) return outFmt().format(d);
            } catch (ParseException ignored) {}
        }
        return s;
    }

    private SimpleDateFormat outFmt() {
        return new SimpleDateFormat("dd/MM/yyyy", Locale.getDefault());
    }
}

